mapper.select:
SELECT MIN(x.company_code) AS company_code, MIN(x.contract_no) AS contract_no, MIN(NULLIF(x.customer_code,'')) AS customer_code, MIN(NULLIF(x.customer_name,'')) AS customer_name, CASE WHEN MAX(x.customer_code_invalid)=1 THEN 'ERP_CUSTOMER_CODE_FORMAT_INVALID' WHEN COUNT(DISTINCT CAST(NULLIF(x.customer_code,'') AS BINARY))>1 OR COUNT(DISTINCT CAST(NULLIF(x.customer_name,'') AS BINARY))>1 THEN 'CONTRACT_CUSTOMER_CONFLICT' ELSE NULL END AS migration_issue FROM ( SELECT o.company_code,o.contract_no,o.customer_name, CASE WHEN o.customer_code IS NULL OR o.customer_code='' THEN o.customer_code WHEN o.customer_code REGEXP '^[A-Za-z]' AND CHAR_LENGTH(TRIM(LEADING '0' FROM SUBSTRING(o.customer_code,2)))<=5 THEN CONCAT(LEFT(o.customer_code,1),LPAD(TRIM(LEADING '0' FROM SUBSTRING(o.customer_code,2)),5,'0')) ELSE NULL END AS customer_code, CASE WHEN o.customer_code IS NOT NULL AND o.customer_code<>'' AND (NOT(o.customer_code REGEXP '^[A-Za-z]') OR CHAR_LENGTH(TRIM(LEADING '0' FROM SUBSTRING(o.customer_code,2)))>5) THEN 1 ELSE 0 END AS customer_code_invalid FROM com_sales_order o WHERE o.tenant_id=#{query.tenantId} AND o.deleted=0 AND o.source_system IN ('SAP','D365','SMS') AND o.company_code IS NOT NULL AND o.company_code<>'' AND o.contract_no IS NOT NULL AND o.contract_no<>''
AND o.contract_no IN #{number}
AND (CAST(o.company_code AS BINARY)>CAST(#{query.afterCompany} AS BINARY) OR CAST(o.company_code AS BINARY)=CAST(#{query.afterCompany} AS BINARY) AND CAST(o.contract_no AS BINARY)>CAST(#{query.afterContract} AS BINARY))
) x GROUP BY CAST(x.company_code AS BINARY),CAST(x.contract_no AS BINARY) ORDER BY CAST(x.company_code AS BINARY),CAST(x.contract_no AS BINARY) LIMIT 500
